   383|            val snaps = query.get().await()
   384|            val results = mutableListOf<HealthCheckupResultDto>()
   385|
   386|            for (snap in snaps.documents) {
   387|                val checkup = snap.toObject(HealthCheckupResultDto::class.java)?.copy(id = snap.id)
   388|                if (checkup != null) {
   389|                    // Enrich with kid name and camp title
   390|                    val enriched = enrichCheckup(checkup, uid)
   391|                    results.add(enriched)
