   408|    private suspend fun enrichCheckup(dto: HealthCheckupResultDto, uid: String): HealthCheckupResultDto {
   409|        var result = dto
   410|        try {
   411|            // Find kid name from any profile's kids subcollection
   412|            if (result.kidName.isBlank()) {
   413|                val kidSnap = db.collectionGroup("kids").whereEqualTo("id", dto.kidId).limit(1).get().await()
   414|                if (!kidSnap.documents.isEmpty()) {
   415|                    result = result.copy(kidName = kidSnap.documents[0].getString("name") ?: "")
   416|                }
   417|            }
   418|            // Find camp title
   419|            if (result.campTitle.isBlank() && dto.schoolCampId.isNotBlank()) {
   420|                val campSnap = db.collection("school_camps").document(dto.schoolCampId).get().await()
   421|                if (campSnap.exists()) {
   422|                    result = result.copy(
   423|                        campTitle = campSnap.getString("title") ?: "",
   424|                        campDate = campSnap.getString("date") ?: "",
   425|                    )
   426|                }
   427|            }
   428|        } catch (_: Exception) { }
   429|        return result
   430|    }
