/** Count documents in a collection (with optional filters). */
async count(collection: string, filters?: Filter[]): Promise<number> {
  const sq: Record<string, unknown> = {
    from: [{ collectionId: collection }],
    aggregation: {
      aggregations: [{ alias: "count", count: {} }],
    },
  };
  if (filters && filters.length > 0) {
    sq.where = this.buildFilter(filters.length === 1 ? filters[0] : { compositeFilter: { op: "AND", filters } });
  }
  const resp = await fetch(`${this.baseUrl}:runAggregationQuery`, {
    method: "POST",
    headers: await this.headers(),
    body: JSON.stringify({ structuredAggregationQuery: sq }),
  });
  if (!resp.ok) return 0;
  const data = await resp.json() as { result?: { aggregateFields?: { count?: { integerValue?: string } } } };
  return parseInt(data.result?.aggregateFields?.count?.integerValue || "0", 10);
}

